fn frame(t: i32) {
    let tab = [0, 49, 90, 117, 127, 117, 90, 49, 0, -49, -90, -117, -127, -117, -90, -49];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let cols: i32 = 16;
    let rows: i32 = 12;
    host::display::clear(0x000008);
    let mut gy: i32 = 0;
    while gy < rows {
        let mut gx: i32 = 0;
        while gx < cols {
            let idx: i32 = (gx * 2 + gy + t / 2) & 15;
            let s: i32 = tab[idx];
            let x: i32 = (gx * 2 + 1) * w / (cols * 2);
            let y: i32 = (gy * 2 + 1) * h / (rows * 2) + s * 10 / 127;
            let c: i32 = if s > 60 { 0x40ffff } else if s > 0 - 60 { 0x2080c0 } else { 0x103060 };
            host::display::fill_rect(x - 2, y - 2, 4, 4, c);
            gx = gx + 1;
        }
        gy = gy + 1;
    }
    host::display::present();
}
